import { Component, ParentComponent, type JSX } from "solid-js";

export interface DividerProps {
	class?: string;
}

/** The visual variant of a ticket section. */
export type TicketSectionVariant = "default" | "negative" | "gold";

/** Horizontal divider line component - spans full width with gradient fade. */
export const Divider: Component<DividerProps> = (props) => (
	<div
		class={`h-0\\.5 flex-auto -ml-6 -mr-6 my-0\\.5 ${props.class ?? ""}`}
		style={{
			"background-image":
				"linear-gradient(90deg, rgba(141, 151, 166, 0) 0%, #8d97a6ff 50%, rgba(141, 151, 166, 0) 100%)",
		}}
	/>
);

/** Entry divider used between rows within a ticket section. Simple semi-transparent line. */
export const EntryDivider: Component<DividerProps> = (props) => (
	<div class={`h-px flex-auto my-0\\.5 bg-accent-2 opacity-30 ${props.class ?? ""}`} />
);

const TICKET_VARIANT_IMAGES: Record<TicketSectionVariant, string> = {
	default: "url(blp:base_ticket-bg)",
	negative: "url(blp:base_ticket-negative_bg)",
	gold: "url(blp:base_ticket-gold_bg)",
};

export interface TicketSectionProps {
	name?: string;
	class?: string;
	/** The visual variant of the ticket background. @default "default" */
	variant?: TicketSectionVariant;
}
/** Generic ticket wrapper used by plot tooltip sections. */
export const TicketSection: ParentComponent<TicketSectionProps> = (props) => (
	<div
		data-name={props.name ?? "TicketSection"}
		class={`img-base-ticket-bg-container mt-1 px-3 py-1\\.5 ${props.class ?? ""}`}
		style={{
			"border-image-source": TICKET_VARIANT_IMAGES[props.variant ?? "default"],
		}}
	>
		{props.children}
	</div>
);

interface TicketRowProps {
	icon?: JSX.Element;
	class?: string;
}

/** Reusable ticket row with left icon, center divider, and right content. */
export const TicketRow: ParentComponent<TicketRowProps> = (props) => (
	<div class={`flex w-full items-center ${props.class ?? ""}`}>
		<div class="w-12 shrink-0 flex items-center justify-center py-0\.5">{props.icon}</div>
		<div class="w-px self-stretch bg-accent-2 opacity-30 mx-2" />
		<div class={`flex flex-col justify-start flex-auto`}>{props.children}</div>
	</div>
);
